@once
<style>
  .dm-modal{position:fixed;inset:0;z-index:1080;display:none;align-items:center;justify-content:center;padding:12px;background:#11182799}
  .dm-modal.open{display:flex}.dm-dialog{width:min(660px,100%);height:min(760px,calc(100dvh - 24px));display:grid;grid-template-rows:auto minmax(0,1fr) auto;background:var(--bs-body-bg,#fff);border-radius:18px;box-shadow:0 24px 60px #0004;overflow:hidden}
  .dm-head,.dm-compose,.dm-list{min-width:0}.dm-head,.dm-compose{padding:14px 16px}.dm-head{border-bottom:1px solid var(--bs-border-color,#e5e7eb)}.dm-compose{border-top:1px solid var(--bs-border-color,#e5e7eb)}
  .dm-list{min-height:0;overflow:auto;padding:16px;display:grid;align-content:start;gap:10px;background:var(--bs-tertiary-bg,#fafafa)}.dm-bubble{max-width:82%;padding:10px 12px;border:1px solid var(--bs-border-color,#e5e7eb);border-radius:14px;white-space:pre-wrap;overflow-wrap:anywhere}.dm-bubble.mine{margin-left:auto;background:var(--primary,#7B3A0F);color:#fff;border-color:transparent}.dm-message-image{display:block;width:112px;height:88px;max-width:100%;margin-top:8px;border-radius:10px;object-fit:cover;cursor:zoom-in}.dm-time{font-size:11px;opacity:.72;margin-top:5px}
  .dm-row{display:flex;min-width:0;gap:8px;align-items:flex-end}.dm-row textarea{flex:1;min-width:0;min-height:44px;border:1px solid #d1d5db;border-radius:12px;padding:10px;font:inherit;resize:none}.dm-row label.btn{display:grid;place-items:center;width:42px;height:44px;min-width:42px;padding:0;overflow:hidden}.dm-row label [id^="img-size-preview-"],.dm-row label .cs-upload-summary{display:none!important}.dm-attachment-preview{position:relative;display:inline-flex;width:56px;height:56px;margin:2px 0 8px;border:1px solid var(--bs-border-color,#d1d5db);border-radius:10px;background:#f8fafc;overflow:visible}.dm-attachment-preview[hidden]{display:none}.dm-attachment-preview img{width:100%;height:100%;border-radius:inherit;object-fit:cover}.dm-attachment-preview button{position:absolute;top:-7px;right:-7px;width:21px;height:21px;padding:0;border:0;border-radius:50%;background:#1f2937;color:#fff;font-size:12px;line-height:1;cursor:pointer}.dm-send,.dm-close,.dm-back{border:0;cursor:pointer;flex:0 0 auto}.dm-send{min-height:44px;background:var(--primary,#7B3A0F);color:#fff;border-radius:12px;padding:10px 14px;font-weight:700}.dm-close{border-radius:50%;width:38px;height:38px}.dm-back{background:transparent;color:var(--bs-secondary-color,#4b5563);font-weight:700;padding:6px 0}.dm-quick{display:flex;max-width:100%;overflow:auto;gap:7px;margin:8px 0}.dm-quick button{white-space:nowrap;border:1px solid #d1d5db;background:var(--bs-body-bg,#fff);border-radius:999px;padding:6px 9px;font-size:12px;cursor:pointer}
  @media (max-width:575.98px){.dm-modal{padding:8px}.dm-dialog{height:calc(100dvh - 16px);border-radius:14px}.dm-head{padding:10px 12px}.dm-compose{padding:8px 10px}.dm-quick{display:none}.dm-row{gap:6px}.dm-row textarea{height:42px;min-height:42px;padding:9px 10px;line-height:1.25}.dm-row label.btn{width:42px;height:42px;min-width:42px}.dm-send{height:42px;min-height:42px;padding:8px 10px;font-size:.8rem;border-radius:10px}.dm-message-image{width:96px;height:76px}}
  @media (max-width:360px){.dm-row label.btn{width:38px;min-width:38px}.dm-send{padding:8px 9px}}
</style>
<div class="dm-modal" id="deliveryMessageModal" aria-hidden="true">
  <section class="dm-dialog" role="dialog" aria-modal="true" aria-labelledby="deliveryMessageTitle" tabindex="-1">
    <header class="dm-head d-flex align-items-center gap-2">
      <button type="button" class="dm-back" aria-label="Back to order" data-dm-close><i class="bi bi-arrow-left"></i></button>
      <div class="flex-grow-1" style="min-width:0"><strong id="deliveryMessageTitle">Delivery messages</strong><div class="small text-muted text-truncate" id="deliveryMessageSubtitle"></div></div>
      <button type="button" class="dm-close" aria-label="Close messages" data-dm-close><i class="bi bi-x-lg"></i></button>
    </header>
    <div class="dm-list" id="deliveryMessageList" aria-live="polite"></div>
    <form class="dm-compose" id="deliveryMessageForm" enctype="multipart/form-data">
      <div class="dm-quick"><button type="button">I'm available to receive the order.</button><button type="button">Please call when you arrive.</button><button type="button">I'm at the delivery location.</button><button type="button">Thank you.</button></div>
      <div class="small text-danger" id="deliveryMessageError" role="alert"></div>
      <div class="dm-attachment-preview" id="deliveryMessageAttachmentPreview" hidden><img alt="Selected image preview"><button type="button" aria-label="Remove selected image" data-dm-clear-image>&times;</button></div>
      <div class="dm-row"><label class="btn btn-light mb-0" title="Attach image"><i class="bi bi-image"></i><input class="d-none" type="file" accept="image/jpeg,image/png,image/webp" name="image" data-cs-hide-optimization="true"></label><textarea name="message" rows="2" maxlength="1000" placeholder="Write a message..." aria-label="Message"></textarea><button class="dm-send" type="submit">Send</button></div>
    </form>
  </section>
</div>
<script>
(() => {
  const modal = document.getElementById('deliveryMessageModal');
  if (!modal || modal.dataset.ready) return;
  modal.dataset.ready = 'true';
  if (modal.parentElement !== document.body) document.body.appendChild(modal);

  const dialog = modal.querySelector('.dm-dialog'), list = document.getElementById('deliveryMessageList'), form = document.getElementById('deliveryMessageForm'), error = document.getElementById('deliveryMessageError'), sub = document.getElementById('deliveryMessageSubtitle'), imageInput = form.querySelector('input[name="image"]'), attachmentPreview = document.getElementById('deliveryMessageAttachmentPreview'), attachmentImage = attachmentPreview.querySelector('img');
  let current, trigger, timer, previousOverflow, attachmentUrl;
  const csrf = @json(csrf_token());
  const clearAttachment = (resetInput = true) => { if (attachmentUrl) URL.revokeObjectURL(attachmentUrl); attachmentUrl = undefined; if (resetInput) imageInput.value = ''; attachmentImage.removeAttribute('src'); attachmentPreview.hidden = true; const generatedPreview = imageInput.dataset.sizePreviewId && document.getElementById(imageInput.dataset.sizePreviewId); generatedPreview?.remove(); };
  const close = () => { modal.classList.remove('open'); modal.setAttribute('aria-hidden', 'true'); document.body.style.overflow = previousOverflow ?? ''; clearInterval(timer); trigger?.focus(); };
  const bubble = message => { const item = document.createElement('article'); item.className = 'dm-bubble ' + (message.sender_type === current.role ? 'mine' : ''); if (message.message) { const text = document.createElement('div'); text.textContent = message.message; item.append(text); } if (message.image_path) { const image = document.createElement('img'); image.className = 'dm-message-image chat-img'; image.src = message.image_path; image.dataset.src = message.image_path; image.alt = 'Open attached image'; image.addEventListener('click', event => { event.stopPropagation(); if (typeof window.openLightbox === 'function') window.openLightbox(image, [message.image_path], 0); }); item.append(image); } const time = document.createElement('div'); time.className = 'dm-time'; time.textContent = new Date(message.created_at).toLocaleString(); item.append(time); return item; };
  const load = async () => { const response = await fetch(current.index, {credentials:'same-origin', headers:{Accept:'application/json'}}); const data = await response.json().catch(() => ({})); if (!response.ok) throw Error(data.message || data.error || 'Conversation is unavailable.'); list.replaceChildren(...(data.messages || []).map(bubble)); if (!data.messages?.length) list.innerHTML = '<div class="text-muted small text-center py-4">No messages yet. Start the conversation.</div>'; list.scrollTop = list.scrollHeight; };
  const open = async button => { trigger = button; current = {index:button.dataset.index, send:button.dataset.send, role:button.dataset.role}; sub.textContent = button.dataset.label || ''; error.textContent = ''; previousOverflow = document.body.style.overflow; modal.classList.add('open'); modal.setAttribute('aria-hidden', 'false'); document.body.style.overflow = 'hidden'; list.textContent = 'Loading conversation...'; try { await load(); form.querySelector('textarea').focus(); timer = setInterval(() => load().catch(() => {}), 10000); } catch (exception) { error.textContent = exception.message; dialog.focus(); } };
  imageInput.addEventListener('change', () => { const file = imageInput.files?.[0]; clearAttachment(false); if (!file) return; attachmentUrl = URL.createObjectURL(file); attachmentImage.src = attachmentUrl; attachmentPreview.hidden = false; });
  document.addEventListener('click', event => { const button = event.target.closest('[data-delivery-message]'); if (button) { event.preventDefault(); open(button); return; } if (event.target.closest('[data-dm-close]') || event.target === modal) close(); if (event.target.closest('[data-dm-clear-image]')) clearAttachment(); const quickReply = event.target.closest('.dm-quick button'); if (quickReply) form.querySelector('textarea').value = quickReply.textContent.trim(); });
  document.addEventListener('keydown', event => { if (!modal.classList.contains('open')) return; const lightbox = document.getElementById('csLightbox'); if (lightbox && lightbox.style.display !== 'none') return; if (event.key === 'Escape') { event.preventDefault(); close(); return; } if (event.key !== 'Tab') return; const focusable = [...dialog.querySelectorAll('button:not([disabled]), textarea:not([disabled]), input:not([disabled])')].filter(element => element.offsetParent !== null); if (!focusable.length) return; const first = focusable[0], last = focusable.at(-1); if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } });
  form.addEventListener('submit', async event => { event.preventDefault(); if (!current) return; const submit = form.querySelector('[type=submit]'); submit.disabled = true; error.textContent = ''; try { const response = await fetch(current.send, {method:'POST', credentials:'same-origin', headers:{'X-CSRF-TOKEN':csrf, Accept:'application/json'}, body:new FormData(form)}); const data = await response.json().catch(() => ({})); if (!response.ok) throw Error(data.errors ? Object.values(data.errors).flat().join(' ') : (data.message || data.error || 'Message could not be sent.')); form.reset(); clearAttachment(false); await load(); } catch (exception) { error.textContent = exception.message; } finally { submit.disabled = false; } });
  setTimeout(() => { const hash = window.location.hash; const target = hash === '#delivery-message' ? document.querySelector('[data-delivery-message]') : document.querySelector(hash + ' [data-delivery-message]'); target?.click(); }, 0);
})();
</script>
@endonce
